    37	@Slf4j
    38	@Configuration
    39	@RequiredArgsConstructor
    40	public class Xkd78JobConfig {
    41	
    42	    private final JobRepository jobRepository;
    43	    private final PlatformTransactionManager transactionManager;
    44	    private final EntityManagerFactory entityManagerFactory;
    45	
    46	    private final Xzm66Repository orderShipmentRepository;
    47	    private final Xss87CommandService notificationService;
    48	    private final Xfr60CommandService orderService;
    49	    private final Xwg86 cjTrackingPlaywright;
    50	
    51	    private static final int CHUNK_SIZE = 50;
    52	    private static final int SKIP_LIMIT = 50;
    53	
    54	    @Bean
    55	    public Job updateShipmentStatusesJob() {
    56	        log.info("배송 상태 업데이트 작업 구성");
    57	        return new JobBuilder("updateShipmentStatusesJob", jobRepository)
    58	                .start(updateShipmentStatusesStep())
    59	                .build();
    60	    }
    61	
    62	    @Bean
    63	    public Step updateShipmentStatusesStep() {
    64	        log.info("배송 상태 업데이트 스텝 구성: 청크 크기={}, 스킵 제한={}", CHUNK_SIZE, SKIP_LIMIT);
    65	
    66	        return new StepBuilder("updateShipmentStatusesStep", jobRepository)
    67	                .<Xfr60, Xfr60>chunk(CHUNK_SIZE, transactionManager)
    68	                .reader(shipmentItemReader())
    69	                .processor(new Xhx91Processor(
    70	                        playwrightBrowserManager(),
    71	                        notificationService,
    72	                        orderService
    73	                ))
    74	                .writer(shipmentJpaItemWriter())
    75	                .faultTolerant()
    76	                .skip(Exception.class)
    77	                .skipLimit(SKIP_LIMIT)
    78	                .listener(shipmentSkipListener())
    79	
    80	                .listener(new Xsn32Listener(playwrightBrowserManager()))
    81	                .build();
    82	    }
