    87	    @Bean
    88	    @StepScope
    89	    public JpaPagingItemReader<Xfr60> shipmentItemReader() {
    90	        log.debug("배송 상태 업데이트 ItemReader 구성");
    91	        return new JpaPagingItemReaderBuilder<Xfr60>()
    92	                .name("shipmentItemReader")
    93	                .entityManagerFactory(entityManagerFactory)
    94	                .pageSize(CHUNK_SIZE)
    95	                .queryString("SELECT s FROM Xfr60 s WHERE s.status IN ('IN_TRANSIT','OUT_FOR_DELIVERY') AND s.trackingNumber IS NOT NULL")
    96	                .build();
    97	    }
