   228	    private Xzn53Status mapToShipmentStatus(String statusText) {
   229	        return switch (statusText) {
   230	            case "배송완료" -> Xzn53Status.DELIVERED;
   231	            case "배송출발" -> Xzn53Status.OUT_FOR_DELIVERY;
   232	            default -> Xzn53Status.IN_TRANSIT;
   233	        };
   234	    }
